mapper.select:
SELECT n.id, n.title, n.notice_type, n.publish_time, (r.id IS NOT NULL) AS read_flag
FROM sys_notice n
LEFT JOIN sys_notice_read r ON r.user_id = #{userId} AND r.notice_id = n.id AND r.deleted = 0
WHERE n.deleted = 0 AND n.status = 0 AND n.publish_time <= #{now}

    AND n.notice_type = #{noticeType}

ORDER BY n.publish_time DESC, n.id DESC
